/* Frozen exact-resource GLES2 atlas feasibility gate. No emulation or cache changes. */
#include <SDL2/SDL.h>
#include <GLES2/gl2.h>
#include <GLES2/gl2ext.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#define DIM 2048
#define LIMIT 4096
#define CHECK(x) do{if(!(x)){fprintf(stderr,"failure line %d: %s\n",__LINE__,#x);exit(2);}}while(0)
typedef struct {float p[3],c[4],uvq[3];} vertex;
typedef struct {vertex v;float region[4];} av;
typedef struct {unsigned tex,count;int scissor[4];vertex *v;unsigned first;} draw;
typedef struct {int w,h,x,y,page;unsigned char *rgba;GLuint tex;} resource;
typedef struct {int x,y,w,h,page;} rect;
static resource res[LIMIT];static draw ds[LIMIT];static int nr,nd,np,nv;static rect free_rect[LIMIT*2];static int nf;static GLuint pages[4],buffer,fb;static float bg[3];static int priority,depth;
static const char *vs="#version 100\nattribute vec3 a_position;attribute vec4 a_colour;attribute vec3 a_uvq;uniform mat4 u_projection;varying mediump vec4 v_colour;varying highp vec3 v_uvq;void main(){gl_Position=u_projection*vec4(a_position,1.0);v_colour=a_colour;v_uvq=a_uvq;}";
static const char *avs="#version 100\nattribute vec3 a_position;attribute vec4 a_colour;attribute vec3 a_uvq;attribute vec4 a_region;uniform mat4 u_projection;varying mediump vec4 v_colour;varying highp vec3 v_uvq;varying highp vec4 v_region;void main(){gl_Position=u_projection*vec4(a_position,1.0);v_colour=a_colour;v_uvq=a_uvq;v_region=a_region;}";
static const char *fs="#version 100\nprecision highp float;uniform sampler2D u_texture;uniform bool u_priority;varying mediump vec4 v_colour;varying highp vec3 v_uvq;void main(){vec2 uv=v_uvq.xy/v_uvq.z;vec4 texel=texture2D(u_texture,uv);if(texel.a==0.0)discard;vec4 c=v_colour*texel;gl_FragColor=u_priority?vec4(c.rgb,v_colour.a):c;}";
static const char *afs="#version 100\nprecision highp float;uniform sampler2D u_texture;uniform bool u_priority;varying mediump vec4 v_colour;varying highp vec3 v_uvq;varying highp vec4 v_region;void main(){vec2 uv=v_uvq.xy/v_uvq.z;vec4 r=floor(v_region+0.5);vec2 t=clamp(floor(uv*r.zw),vec2(0.0),r.zw-1.0);vec4 texel=texture2D(u_texture,(r.xy+t+0.5)/2048.0);if(texel.a==0.0)discard;vec4 c=v_colour*texel;gl_FragColor=u_priority?vec4(c.rgb,v_colour.a):c;}";
static const char *affs="#version 100\nprecision highp float;uniform sampler2D u_texture;uniform bool u_priority;varying mediump vec4 v_colour;varying highp vec3 v_uvq;varying highp vec4 v_region;void main(){vec2 uv=v_uvq.xy/v_uvq.z;vec4 r=floor(v_region+0.5);vec2 t=clamp(uv*r.zw,vec2(0.5),r.zw-0.5);vec4 texel=texture2D(u_texture,(r.xy+t)/2048.0);if(texel.a==0.0)discard;vec4 c=v_colour*texel;gl_FragColor=u_priority?vec4(c.rgb,v_colour.a):c;}";
static GLuint program(const char *v,const char *f){GLuint p=glCreateProgram();const char *s[2]={v,f};for(int i=0;i<2;i++){GLuint q=glCreateShader(i?GL_FRAGMENT_SHADER:GL_VERTEX_SHADER);glShaderSource(q,1,s+i,NULL);glCompileShader(q);GLint ok;glGetShaderiv(q,GL_COMPILE_STATUS,&ok);if(!ok){char log[4096];glGetShaderInfoLog(q,sizeof log,0,log);fprintf(stderr,"%s\n",log);exit(2);}glAttachShader(p,q);glDeleteShader(q);}const char *attrs[]={"a_position","a_colour","a_uvq","a_region"};for(int i=0;i<4;i++)glBindAttribLocation(p,i,attrs[i]);glLinkProgram(p);GLint ok;glGetProgramiv(p,GL_LINK_STATUS,&ok);CHECK(ok);return p;}
static GLuint texture(int w,int h,const void *pixels){GLuint t;glGenTextures(1,&t);glBindTexture(GL_TEXTURE_2D,t);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MIN_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_MAG_FILTER,GL_NEAREST);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_S,GL_CLAMP_TO_EDGE);glTexParameteri(GL_TEXTURE_2D,GL_TEXTURE_WRAP_T,GL_CLAMP_TO_EDGE);glTexImage2D(GL_TEXTURE_2D,0,GL_RGBA,w,h,0,GL_RGBA,GL_UNSIGNED_BYTE,pixels);return t;}
static double now(clockid_t id){struct timespec t;clock_gettime(id,&t);return t.tv_sec+t.tv_nsec*1e-9;}
static void load(const char *dir){char path[1024];snprintf(path,sizeof path,"%s/scene.meta",dir);FILE *f=fopen(path,"r");CHECK(f&&fscanf(f,"%f %f %f %d %d",bg,bg+1,bg+2,&priority,&depth)==5);fclose(f);snprintf(path,sizeof path,"%s/draws.bin",dir);f=fopen(path,"rb");CHECK(f);uint32_t h[6];while(fread(h,4,6,f)==6){CHECK(nd<LIMIT&&h[0]<LIMIT);draw *d=ds+nd++;d->tex=h[0];d->count=h[1];CHECK(d->count<=60000);memcpy(d->scissor,h+2,16);d->first=nv;nv+=d->count;d->v=malloc(d->count*sizeof(vertex));CHECK(d->v&&fread(d->v,sizeof(vertex),d->count,f)==d->count);if((int)d->tex>=nr)nr=d->tex+1;}CHECK(feof(f));fclose(f);for(int i=0;i<nr;i++){snprintf(path,sizeof path,"%s/texture-%d.rgba",dir,i);f=fopen(path,"rb");CHECK(f&&fscanf(f,"%d %d",&res[i].w,&res[i].h)==2);fgetc(f);resource *r=res+i;CHECK(r->w>0&&r->w<=1025&&r->h>0&&r->h<=1025);r->rgba=malloc((size_t)r->w*r->h*4);CHECK(r->rgba&&fread(r->rgba,4,(size_t)r->w*r->h,f)==(size_t)r->w*r->h);fclose(f);}}
static int cmp_resource(const void *a,const void *b){int x=*(const int*)a,y=*(const int*)b;return res[y].w*res[y].h-res[x].w*res[x].h;}
static void pack(void){int order[LIMIT];size_t payload=0;for(int i=0;i<nr;i++)order[i]=i;qsort(order,nr,sizeof(int),cmp_resource);for(int n=0;n<nr;n++){resource *r=res+order[n];int w=r->w,h=r->h,best=-1,score=2147483647;for(int i=0;i<nf;i++){rect q=free_rect[i];int spare=q.w*q.h-w*h;if(q.w>=w&&q.h>=h&&spare<score){best=i;score=spare;}}if(best<0){CHECK(np<4);pages[np]=texture(DIM,DIM,NULL);free_rect[nf++]=(rect){0,0,DIM,DIM,np++};best=nf-1;}rect q=free_rect[best];free_rect[best]=free_rect[--nf];r->x=q.x;r->y=q.y;r->page=q.page;if(q.w>w)free_rect[nf++]=(rect){q.x+w,q.y,q.w-w,h,q.page};if(q.h>h)free_rect[nf++]=(rect){q.x,q.y+h,q.w,q.h-h,q.page};CHECK(nf<LIMIT*2);glBindTexture(GL_TEXTURE_2D,pages[r->page]);glTexSubImage2D(GL_TEXTURE_2D,0,r->x,r->y,w,h,GL_RGBA,GL_UNSIGNED_BYTE,r->rgba);payload+=(size_t)w*h*4;r->tex=texture(w,h,r->rgba);}printf("resources=%d draws=%d vertices=%d pages=%d payload=%zu page_bytes=%zu occupancy=%.6f\n",nr,nd,nv,np,payload,(size_t)np*DIM*DIM*4,(double)payload/(np*DIM*DIM*4));}
static unsigned submit(GLuint p,int mode,int affine,unsigned char *pixels,double *cpu,double *wall){vertex *v=malloc(nv*sizeof(vertex));av *a=malloc(nv*sizeof(av));CHECK(v&&a);for(int i=0;i<nd;i++){draw *d=ds+i;resource *r=res+d->tex;memcpy(v+d->first,d->v,d->count*sizeof(vertex));for(unsigned j=0;j<d->count;j++){a[d->first+j].v=d->v[j];float *region=a[d->first+j].region;region[0]=r->x;region[1]=r->y;region[2]=r->w;region[3]=r->h;}}
 double start=now(CLOCK_MONOTONIC),begin=now(CLOCK_THREAD_CPUTIME_ID);glBindFramebuffer(GL_FRAMEBUFFER,fb);glViewport(0,0,640,480);glDisable(GL_CULL_FACE);glDisable(GL_SCISSOR_TEST);if(priority)glDisable(GL_BLEND);else {glEnable(GL_BLEND);glBlendFunc(GL_SRC_ALPHA,GL_ONE_MINUS_SRC_ALPHA);}glEnable(GL_DEPTH_TEST);glDepthFunc(GL_LEQUAL);glDepthMask(GL_TRUE);glClearDepthf(1);glClearColor(bg[0],bg[1],bg[2],priority?0:1);glClear(GL_COLOR_BUFFER_BIT|GL_DEPTH_BUFFER_BIT);glEnable(GL_SCISSOR_TEST);glUseProgram(p);const float matrix[16]={2.f/640,0,0,0,0,-2.f/480,0,0,0,0,1,0,-1,1,0,1};glUniformMatrix4fv(glGetUniformLocation(p,"u_projection"),1,GL_FALSE,matrix);glUniform1i(glGetUniformLocation(p,"u_priority"),priority);glUniform1i(glGetUniformLocation(p,"u_texture"),0);glActiveTexture(GL_TEXTURE0);glBindBuffer(GL_ARRAY_BUFFER,buffer);glBufferData(GL_ARRAY_BUFFER,nv*(mode?sizeof(av):sizeof(vertex)),mode?(void*)a:(void*)v,GL_STREAM_DRAW);int stride=mode?sizeof(av):sizeof(vertex);glVertexAttribPointer(0,3,GL_FLOAT,GL_FALSE,stride,(void*)0);glVertexAttribPointer(1,4,GL_FLOAT,GL_FALSE,stride,(void*)12);glVertexAttribPointer(2,3,GL_FLOAT,GL_FALSE,stride,(void*)28);for(int i=0;i<3;i++)glEnableVertexAttribArray(i);if(mode){glVertexAttribPointer(3,4,GL_FLOAT,GL_FALSE,stride,(void*)40);glEnableVertexAttribArray(3);}else glDisableVertexAttribArray(3);
 unsigned draws=0;for(int i=0;i<nd;){draw *d=ds+i;int end=i+1,count=d->count;if(mode==2)while(end<nd&&res[ds[end].tex].page==res[d->tex].page&&!memcmp(ds[end].scissor,d->scissor,16)){count+=ds[end++].count;}glScissor(d->scissor[0],d->scissor[1],d->scissor[2],d->scissor[3]);glBindTexture(GL_TEXTURE_2D,mode?pages[res[d->tex].page]:res[d->tex].tex);glDrawArrays(GL_TRIANGLES,d->first,count);draws++;i=end;}*cpu=now(CLOCK_THREAD_CPUTIME_ID)-begin;glFinish();*wall=now(CLOCK_MONOTONIC)-start;if(pixels)glReadPixels(0,0,640,480,GL_RGBA,GL_UNSIGNED_BYTE,pixels);CHECK(glGetError()==GL_NO_ERROR);free(v);free(a);return draws;}
static unsigned compare(const char *label,unsigned char *a,unsigned char *b){unsigned n=0;for(int i=0;i<640*480;i++)n+=memcmp(a+i*4,b+i*4,4)!=0;printf("%s differing_pixels=%u\n",label,n);FILE *f=fopen(label,"wb");CHECK(f);fwrite(b,4,640*480,f);fclose(f);return n;}
int main(int argc,char **argv){CHECK(argc==2);CHECK(!SDL_Init(SDL_INIT_VIDEO));SDL_GL_SetAttribute(SDL_GL_CONTEXT_PROFILE_MASK,SDL_GL_CONTEXT_PROFILE_ES);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MAJOR_VERSION,2);SDL_GL_SetAttribute(SDL_GL_CONTEXT_MINOR_VERSION,0);SDL_Window *w=SDL_CreateWindow("atlas frozen",0,0,640,480,SDL_WINDOW_OPENGL);CHECK(w);CHECK(SDL_GL_CreateContext(w));SDL_GL_SetSwapInterval(0);printf("GPU=%s\n",glGetString(GL_RENDERER));load(argv[1]);pack();GLuint target=texture(640,480,NULL),depthbuf;glGenFramebuffers(1,&fb);glBindFramebuffer(GL_FRAMEBUFFER,fb);glFramebufferTexture2D(GL_FRAMEBUFFER,GL_COLOR_ATTACHMENT0,GL_TEXTURE_2D,target,0);glGenRenderbuffers(1,&depthbuf);glBindRenderbuffer(GL_RENDERBUFFER,depthbuf);glRenderbufferStorage(GL_RENDERBUFFER,depth==16?GL_DEPTH_COMPONENT16:GL_DEPTH_COMPONENT24_OES,640,480);glFramebufferRenderbuffer(GL_FRAMEBUFFER,GL_DEPTH_ATTACHMENT,GL_RENDERBUFFER,depthbuf);CHECK(glCheckFramebufferStatus(GL_FRAMEBUFFER)==GL_FRAMEBUFFER_COMPLETE);glGenBuffers(1,&buffer);GLuint ps[3]={program(vs,fs),program(avs,afs),program(avs,affs)};unsigned char *base=malloc(640*480*4),*candidate=malloc(640*480*4),*reference=malloc(640*480*4);char path[1024];snprintf(path,sizeof path,"%s/reference.rgba",argv[1]);FILE *f=fopen(path,"rb");CHECK(f&&fread(reference,4,640*480,f)==640*480);fclose(f);double cpu,wall;submit(ps[0],0,0,base,&cpu,&wall);unsigned fidelity=compare("baseline.rgba",reference,base);if(strstr((const char*)glGetString(GL_RENDERER),"Mali"))CHECK(!fidelity);int passed[3]={1,0,0};for(int shader=1;shader<=2;shader++){
 unsigned draws=submit(ps[shader],1,shader==2,candidate,&cpu,&wall);char label[80];snprintf(label,sizeof label,"%s-ordered.rgba",shader==1?"integer":"affine");unsigned diff=compare(label,base,candidate);printf("MODE shader=%d mode=1 draws=%u cpu_ms=%.6f finish_wall_ms=%.6f\n",shader,draws,cpu*1000,wall*1000);if(diff)continue;
 draws=submit(ps[shader],2,shader==2,candidate,&cpu,&wall);snprintf(label,sizeof label,"%s-adjacent.rgba",shader==1?"integer":"affine");diff=compare(label,base,candidate);printf("MODE shader=%d mode=2 draws=%u cpu_ms=%.6f finish_wall_ms=%.6f\n",shader,draws,cpu*1000,wall*1000);passed[shader]=!diff;
 }
 if(!passed[1]){fprintf(stderr,"Sampling gate failed; timing and further draw grouping skipped.\n");return 3;}

 for(int warm=0;warm<3;warm++)for(int mode=0;mode<3;mode++)submit(ps[mode?1:0],mode,0,NULL,&cpu,&wall);
 for(int sample=0;sample<20;sample++)for(int step=0;step<3;step++){int mode=(step+sample)%3;unsigned draws=submit(ps[mode?1:0],mode,0,NULL,&cpu,&wall);printf("TIMING sample=%d mode=%d draws=%u cpu_ms=%.6f finish_wall_ms=%.6f\n",sample,mode,draws,cpu*1000,wall*1000);}return 0;}
